// GÉNÉRÉ par scripts/gen-comprendre.mjs à partir de maquettes/v7-comprendre/ : ne pas modifier à la main.
export const cmpTemplate: string = "<div class=\"cmp\">\n<svg width=\"0\" height=\"0\" aria-hidden=\"true\" style=\"position:absolute\"><defs>\n<symbol id=\"s-sun\" viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"4\"/><path d=\"M12 2.5v2.2M12 19.3v2.2M2.5 12h2.2M19.3 12h2.2M5.3 5.3l1.6 1.6M17.1 17.1l1.6 1.6M18.7 5.3l-1.6 1.6M6.9 17.1l-1.6 1.6\"/></symbol>\n<symbol id=\"s-moon\" viewBox=\"0 0 24 24\"><path d=\"M12 3a6 6 0 0 0 9 9 9 9 0 1 1-9-9Z\"/></symbol>\n<symbol id=\"s-star\" viewBox=\"0 0 24 24\"><path d=\"M12 2.6l2.9 6 6.6.9-4.8 4.6 1.2 6.5L12 17.5l-5.9 3.1 1.2-6.5L2.5 9.5l6.6-.9L12 2.6z\"/></symbol>\n<symbol id=\"s-cloud\" viewBox=\"0 0 24 24\"><path d=\"M17.5 19H9a7 7 0 1 1 6.71-9h1.79a4.5 4.5 0 1 1 0 9Z\"/></symbol>\n<symbol id=\"s-bottle\" viewBox=\"0 0 24 24\"><path d=\"M8 2h8M9 2v2.8a4 4 0 0 1-.7 2.2l-.6 1A4 4 0 0 0 7 10.2V20a2 2 0 0 0 2 2h6a2 2 0 0 0 2-2v-9.8a4 4 0 0 0-.7-2.2l-.6-1A4 4 0 0 1 15 4.8V2M7 15a6.5 6.5 0 0 1 5 0 6.5 6.5 0 0 0 5 0\"/></symbol>\n<symbol id=\"s-flower\" viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"2.3\"/><circle cx=\"12\" cy=\"5.4\" r=\"2.6\"/><circle cx=\"17.7\" cy=\"8.7\" r=\"2.6\"/><circle cx=\"17.7\" cy=\"15.3\" r=\"2.6\"/><circle cx=\"12\" cy=\"18.6\" r=\"2.6\"/><circle cx=\"6.3\" cy=\"15.3\" r=\"2.6\"/><circle cx=\"6.3\" cy=\"8.7\" r=\"2.6\"/></symbol>\n<symbol id=\"s-heart\" viewBox=\"0 0 24 24\"><path d=\"M19 14c1.5-1.5 3-3.2 3-5.5A5.5 5.5 0 0 0 16.5 3c-1.8 0-3 .5-4.5 2-1.5-1.5-2.7-2-4.5-2A5.5 5.5 0 0 0 2 8.5c0 2.3 1.5 4 3 5.5l7 7Z\"/></symbol>\n<symbol id=\"s-drop\" viewBox=\"0 0 24 24\"><path d=\"M12 2.7s6 6.1 6 10.3a6 6 0 0 1-12 0c0-4.2 6-10.3 6-10.3z\"/></symbol>\n<symbol id=\"s-smile\" viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M8 14s1.5 2 4 2 4-2 4-2M9 9.2h.01M15 9.2h.01\"/></symbol>\n<symbol id=\"s-roll\" viewBox=\"0 0 24 24\"><path d=\"M21 12a9 9 0 0 1-15.4 6.4L3 16M3 21v-5h5M3 12A9 9 0 0 1 18.4 5.6L21 8M21 3v5h-5\"/></symbol>\n</defs></svg>\n<div class=\"cp-scroll\">\n<!-- ===== En-tête ===== -->\n<div class=\"cp-head\"><h1>Comprendre</h1></div>\n\n<!-- ===== 1. Portrait ===== -->\n<section class=\"cp-pcard\" aria-label=\"Son portrait\">\n<div class=\"cp-ph\"><h2 class=\"cp-h2\" style=\"margin:0\">Son portrait</h2><span class=\"cp-age\">{{ageLine}}</span></div>\n<div class=\"cp-hero\">\n<dc-import name=\"Filou\" situation=\"{{sit}}\" age=\"{{heroAge}}\" medal=\"{{medalOn}}\" symbol=\"{{medalSym}}\" paci=\"{{paciOn}}\" defs=\"{{yes}}\" skip-tick=\"{{skip}}\" on-pose=\"{{onPose}}\" on-tap=\"{{onFoxTap}}\" hint-size=\"358px,270px\"></dc-import>\n<sc-if value=\"{{celOn}}\" hint-placeholder-val=\"{{ false }}\">\n<div class=\"cp-cel\" aria-hidden=\"true\"><i class=\"cp-cf c1\"></i><i class=\"cp-cf c2\"></i><i class=\"cp-cf c3\"></i><i class=\"cp-cf c4\"></i><i class=\"cp-cf c5\"></i><i class=\"cp-cf c6\"></i><i class=\"cp-cf c7\"></i><i class=\"cp-cf c8\"></i><i class=\"cp-cf c9\"></i><i class=\"cp-cf c10\"></i><i class=\"cp-cf c11\"></i><i class=\"cp-cf c12\"></i><b class=\"cp-spk k1\">✦</b><b class=\"cp-spk k2\">✦</b><b class=\"cp-spk k3\">✦</b><b class=\"cp-spk k4\">✦</b><b class=\"cp-spk k5\">✦</b><b class=\"cp-spk k6\">✦</b><span class=\"cp-cel-badge cp-patch {{cel.tint}}\"><svg class=\"cp-sym {{cel.dash}}\" viewBox=\"0 0 24 24\"><use href=\"{{cel.href}}\"/></svg></span></div>\n</sc-if>\n<sc-if value=\"{{bubOn}}\" hint-placeholder-val=\"{{ false }}\">\n<div class=\"cp-bub\" role=\"status\">\n<span class=\"cp-bub-t\">{{bub.t}}</span>\n<sc-if value=\"{{bub.has}}\" hint-placeholder-val=\"{{ true }}\"><button class=\"cp-bub-l\" type=\"button\" onClick=\"{{bub.open}}\">Voir pourquoi</button></sc-if>\n<button class=\"cp-bub-x\" type=\"button\" aria-label=\"Fermer\" onClick=\"{{hideBub}}\"><svg class=\"cp-ic\" viewBox=\"0 0 24 24\"><path d=\"M6 6l12 12M18 6L6 18\"/></svg></button>\n</div>\n</sc-if>\n</div>\n<sc-if value=\"{{celOn}}\" hint-placeholder-val=\"{{ false }}\">\n<div class=\"cp-celc\" role=\"status\"><b class=\"cp-celc-t\">Une nouvelle habitude !</b><p class=\"cp-celc-p\">{{cel.phrase}}</p><sc-if value=\"{{cel.hasMore}}\" hint-placeholder-val=\"{{ false }}\"><p class=\"cp-celc-m\">{{cel.more}}</p></sc-if><div class=\"cp-celc-b\"><button class=\"cp-celc-v\" type=\"button\" onClick=\"{{celOpen}}\">Voir pourquoi</button><button class=\"cp-celc-ok\" type=\"button\" onClick=\"{{ackNew}}\">Génial !</button></div></div>\n</sc-if>\n<div class=\"cp-chiprow\">\n<span class=\"cp-chip\"><i class=\"cp-dot {{chipDot}}\"></i>{{chipA}}</span>\n<span class=\"cp-chip2\">{{chipB}}</span>\n</div>\n<button class=\"cp-ribbtn\" type=\"button\" aria-label=\"Accès à son portrait : ses habitudes qui se dessinent et ses badges gagnés\" onClick=\"{{openAlbum}}\">\n<span class=\"cp-rib-h\"><b>Habitudes et badges</b><span>Accès à son portrait<svg class=\"cp-ic\" viewBox=\"0 0 24 24\" style=\"width:18px;height:18px\"><path d=\"M9 6l6 6-6 6\"/></svg></span></span>\n<span class=\"cp-rib\" style=\"display:flex\">\n<sc-for list=\"{{ribItems}}\" as=\"r\" hint-placeholder-count=\"6\">\n<span class=\"cp-rib-p {{r.cls}}\"><svg class=\"cp-sym {{r.dash}}\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><use href=\"{{r.href}}\"/></svg></span>\n</sc-for>\n<sc-if value=\"{{ribEmpty}}\" hint-placeholder-val=\"{{ false }}\"><span class=\"cp-rib-g\"><svg class=\"cp-sym dash\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><use href=\"#s-sun\"/></svg></span><span class=\"cp-rib-g\"><svg class=\"cp-sym dash\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><use href=\"#s-cloud\"/></svg></span><span class=\"cp-rib-g\"><svg class=\"cp-sym dash\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><use href=\"#s-bottle\"/></svg></span><span class=\"cp-rib-g\"><svg class=\"cp-sym dash\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><use href=\"#s-moon\"/></svg></span></sc-if>\n</span>\n<sc-if value=\"{{ribEmpty}}\" hint-placeholder-val=\"{{ false }}\"><span class=\"cp-rib-lg\"><span><i class=\"cp-lg-d\"></i>Une habitude qui se dessine</span><span><i class=\"cp-lg-s\"></i>Un badge gagné</span></span></sc-if>\n</button>\n</section>\n\n<!-- ===== 2. À retenir ===== -->\n<section>\n<h2 class=\"cp-h2\">À retenir aujourd'hui</h2>\n<p class=\"cp-sub\">Ce qui mérite un coup d'œil, avec sa base de calcul.</p>\n<sc-if value=\"{{keepsEmpty}}\" hint-placeholder-val=\"{{ false }}\"><div class=\"cp-empty\">{{keepsMsg}}</div></sc-if>\n<sc-if value=\"{{keepsFull}}\" hint-placeholder-val=\"{{ true }}\">\n<div class=\"cp-keeps\">\n<sc-for list=\"{{keeps}}\" as=\"k\" hint-placeholder-count=\"3\">\n<button class=\"cp-keep\" type=\"button\" onClick=\"{{k.open}}\">\n<span class=\"cp-patch {{k.tint}}\"><svg class=\"cp-sym\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><use href=\"{{k.href}}\"/></svg></span>\n<span><span class=\"cp-keep-t\">{{k.title}}</span>\n<span class=\"cp-keep-m\"><span class=\"cp-pill {{k.stCls}}\">{{k.stLab}}</span><span class=\"cp-keep-b\">{{k.base}}</span></span></span>\n<svg class=\"cp-ic\" viewBox=\"0 0 24 24\" style=\"color:var(--mut)\"><path d=\"M9 6l6 6-6 6\"/></svg>\n<sc-if value=\"{{k.fresh}}\" hint-placeholder-val=\"{{ false }}\"><i class=\"cp-new\" aria-label=\"Nouveau\"></i></sc-if>\n</button>\n</sc-for>\n</div>\n</sc-if>\n</section>\n\n<!-- ===== 3. Son rythme en un regard ===== -->\n<section>\n<h2 class=\"cp-h2\">Son rythme en un regard</h2>\n<p class=\"cp-sub\">Ce qui revient d'un jour à l'autre.</p>\n<div class=\"cp-car\" ref=\"{{setCar}}\" onScroll=\"{{onCar}}\" role=\"group\" aria-label=\"Ses repères, deux par deux\">\n<sc-for list=\"{{tilePages}}\" as=\"pg\" hint-placeholder-count=\"3\">\n<div class=\"cp-pg\">\n<sc-for list=\"{{pg.items}}\" as=\"t\" hint-placeholder-count=\"2\">\n<button class=\"cp-tile {{t.ti}}\" type=\"button\" onClick=\"{{t.go}}\">\n<svg class=\"cp-ic cp-tile-ch\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M9 6l6 6-6 6\"/></svg>\n<span class=\"cp-tile-k\"><svg class=\"cp-sym\" viewBox=\"0 0 24 24\" style=\"width:18px;height:18px\" aria-hidden=\"true\"><use href=\"{{t.href}}\"/></svg>{{t.k}}</span>\n<span class=\"cp-tile-v\">{{t.v}}</span>\n<span class=\"cp-tile-s\">{{t.s}}</span>\n<span class=\"cp-dots\"><sc-for list=\"{{t.dots}}\" as=\"d\" hint-placeholder-count=\"3\"><i class=\"{{d}}\"></i></sc-for></span>\n</button>\n</sc-for>\n</div>\n</sc-for>\n</div>\n<div class=\"cp-pdots\" role=\"group\" aria-label=\"Pages des repères\"><sc-for list=\"{{pdots}}\" as=\"d\" hint-placeholder-count=\"3\"><button class=\"cp-pd {{d.cls}}\" type=\"button\" aria-label=\"{{d.l}}\" onClick=\"{{d.go}}\"></button></sc-for></div>\n<p class=\"cp-basis\">{{basis}}</p>\n</section>\n\n<!-- ===== 4. Sa journée / Sa nuit ===== -->\n<section ref=\"{{setJ}}\">\n<h2 class=\"cp-h2\">Sa journée, sa nuit</h2>\n<p class=\"cp-sub\">Une journée type, une nuit type.</p>\n<div class=\"cp-card\">\n<div class=\"cp-seg {{segFold}}\" role=\"group\" aria-label=\"Journée ou nuit\">\n<button type=\"button\" class=\"{{segDay}}\" aria-expanded=\"{{dayExp}}\" onClick=\"{{showDay}}\">Sa journée</button>\n<button type=\"button\" class=\"{{segNight}}\" aria-expanded=\"{{nightExp}}\" onClick=\"{{showNight}}\">Sa nuit</button>\n</div>\n<sc-if value=\"{{jOpen}}\" hint-placeholder-val=\"{{ false }}\">\n<div style=\"margin-top:14px\">\n<sc-if value=\"{{frEmpty}}\" hint-placeholder-val=\"{{ false }}\"><div class=\"cp-empty\">{{frMsg}}</div></sc-if>\n<sc-if value=\"{{frFull}}\" hint-placeholder-val=\"{{ true }}\">\n<p class=\"cp-brief\">{{brief}}</p>\n<div class=\"cp-fr {{frCls}}\">\n<sc-for list=\"{{caps}}\" as=\"c\" hint-placeholder-count=\"4\"><i class=\"cp-cap\" style=\"left:{{c.l}};width:{{c.w}}\"></i></sc-for>\n<sc-for list=\"{{dots}}\" as=\"m\" hint-placeholder-count=\"6\"><i class=\"cp-md\" style=\"left:{{m.l}}\"></i></sc-for>\n<sc-for list=\"{{axis}}\" as=\"a\" hint-placeholder-count=\"4\"><span class=\"cp-ax {{a.cls}}\" style=\"left:{{a.l}}\">{{a.t}}</span></sc-for>\n</div>\n<div class=\"cp-meal-l\">{{mealLab}}</div>\n<div class=\"cp-meals\"><sc-for list=\"{{mealPills}}\" as=\"p\" hint-placeholder-count=\"6\"><b>{{p}}</b></sc-for></div>\n<sc-if value=\"{{dayView}}\" hint-placeholder-val=\"{{ true }}\">\n<p class=\"cp-lastn\">{{lastDayLine}}</p>\n<p class=\"cp-basis\">{{frBase}}</p>\n</sc-if>\n<sc-if value=\"{{nightView}}\" hint-placeholder-val=\"{{ false }}\">\n<p class=\"cp-lastn\">{{lastNightLine}}</p>\n<p class=\"cp-basis\">{{frBase}}</p>\n</sc-if>\n<button class=\"cp-fold\" type=\"button\" onClick=\"{{openSteps}}\"><span>Étape par étape</span><svg class=\"cp-ic\" viewBox=\"0 0 24 24\"><path d=\"M9 6l6 6-6 6\"/></svg></button>\n</sc-if>\n</div>\n</sc-if>\n</div>\n</section>\n\n<!-- ===== 5. Ce qui change ===== -->\n<section>\n<h2 class=\"cp-h2\">Ce qui change</h2>\n<p class=\"cp-sub\">Toujours comparé à lui-même, jamais à une norme.</p>\n<div class=\"cp-card\">\n<sc-if value=\"{{chEmpty}}\" hint-placeholder-val=\"{{ false }}\"><div class=\"cp-empty\">Il faut au moins 3 semaines notées pour voir ce qui change. Rien à faire de plus : cela se remplit tout seul.</div></sc-if>\n<sc-if value=\"{{chFull}}\" hint-placeholder-val=\"{{ true }}\">\n<div class=\"cp-chips {{chFold}}\" role=\"group\" aria-label=\"Ce qui change\">\n<sc-for list=\"{{chChips}}\" as=\"c\" hint-placeholder-count=\"4\"><button type=\"button\" class=\"{{c.cls}}\" aria-expanded=\"{{c.exp}}\" onClick=\"{{c.pick}}\">{{c.l}}</button></sc-for>\n</div>\n<sc-if value=\"{{cOpen}}\" hint-placeholder-val=\"{{ false }}\">\n<p class=\"cp-q\">{{chQ}}</p>\n<div class=\"cp-bars\">\n<sc-for list=\"{{chBars}}\" as=\"b\" hint-placeholder-count=\"6\">\n<div class=\"cp-bcol\"><span class=\"cp-bv\">{{b.v}}</span><div class=\"cp-bt\"><div class=\"cp-bf {{b.cls}}\" style=\"height:{{b.h}}\"></div></div><span class=\"cp-bl\">{{b.l}}</span></div>\n</sc-for>\n</div>\n<p class=\"cp-phr\">{{chPh}}</p>\n<div class=\"cp-meta\"><span class=\"cp-pill {{chStCls}}\">{{chStLab}}</span><small>{{chBase}}</small></div>\n<p class=\"cp-alt\">Une semaine seule ne fait pas une tendance.</p>\n</sc-if>\n</sc-if>\n</div>\n</section>\n\n<!-- ===== 6. Aller plus loin ===== -->\n<section>\n<h2 class=\"cp-h2\">Aller plus loin</h2>\n<p class=\"cp-sub\">Pour comprendre le pourquoi du comment.</p>\n<div class=\"cp-more\">\n<sc-for list=\"{{moreCards}}\" as=\"m\" hint-placeholder-count=\"4\">\n<button class=\"cp-mc\" type=\"button\" onClick=\"{{m.open}}\">\n<span class=\"cp-patch {{m.tint}}\"><svg class=\"cp-sym\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><use href=\"{{m.href}}\"/></svg></span>\n<span class=\"cp-mc-t\">{{m.t}}</span>\n<span class=\"cp-mc-l\">{{m.line}}</span>\n<span class=\"cp-mc-k\">{{m.key}}</span>\n</button>\n</sc-for>\n</div>\n<p class=\"cp-basis\" style=\"margin-top:14px\">Ces repères décrivent ses habitudes. Ils ne remplacent pas un avis médical.</p>\n</section>\n</div>\n<dc-import name=\"Portal\">\n<!-- ===== Feuille : étape par étape ===== -->\n<sc-if value=\"{{showSteps}}\" hint-placeholder-val=\"{{ false }}\">\n<div class=\"cp-scrim\"><button class=\"cp-scrim-bg\" type=\"button\" aria-label=\"Fermer\" onClick=\"{{closeSheet}}\"></button>\n<section class=\"cp-sheet\" role=\"dialog\" aria-modal=\"true\" aria-label=\"Étape par étape\">\n<div class=\"cp-grab\"></div>\n<div class=\"cp-sh-h\"><h2>{{stepsTitle}}</h2><button class=\"cp-x\" type=\"button\" aria-label=\"Fermer\" onClick=\"{{closeSheet}}\"><svg class=\"cp-ic\" viewBox=\"0 0 24 24\"><path d=\"M6 6l12 12M18 6L6 18\"/></svg></button></div>\n<div class=\"cp-steps\">\n<sc-for list=\"{{steps}}\" as=\"s\" hint-placeholder-count=\"6\">\n<sc-if value=\"{{s.isGap}}\" hint-placeholder-val=\"{{ false }}\"><div class=\"cp-gap\"><span></span><span class=\"cp-gap-l\">{{s.l}}</span></div></sc-if>\n<sc-if value=\"{{s.isStep}}\" hint-placeholder-val=\"{{ true }}\"><div class=\"cp-step\"><span class=\"cp-step-t\">{{s.t}}</span><span><span class=\"cp-step-l\">{{s.l}}</span> <span class=\"cp-step-d\">{{s.d}}</span></span><span class=\"cp-dots\" style=\"padding:0;color:var(--lav)\"><sc-for list=\"{{s.dots}}\" as=\"d\" hint-placeholder-count=\"3\"><i class=\"{{d}}\"></i></sc-for></span></div></sc-if>\n</sc-for>\n</div>\n<p class=\"cp-basis\">Les points : plus il y en a, plus ce moment revient à la même heure.</p>\n<p class=\"cp-basis\" style=\"margin-top:4px\">{{stepsBase}}</p>\n</section></div>\n</sc-if>\n\n<!-- ===== Feuille : une découverte ===== -->\n<sc-if value=\"{{showDisc}}\" hint-placeholder-val=\"{{ false }}\">\n<div class=\"cp-scrim\"><button class=\"cp-scrim-bg\" type=\"button\" aria-label=\"Fermer\" onClick=\"{{closeSheet}}\"></button>\n<section class=\"cp-sheet\" role=\"dialog\" aria-modal=\"true\" aria-label=\"Une découverte\">\n<div class=\"cp-grab\"></div>\n<div class=\"cp-sh-h\"><span class=\"cp-patch {{disc.tint}}\" style=\"width:52px;height:52px\"><svg class=\"cp-sym {{disc.dash}}\" viewBox=\"0 0 24 24\" style=\"width:32px;height:32px\" aria-hidden=\"true\"><use href=\"{{disc.href}}\"/></svg></span><span class=\"cp-pill {{disc.stCls}}\">{{disc.stLab}}</span><span style=\"flex:1\"></span><button class=\"cp-x\" type=\"button\" aria-label=\"Fermer\" onClick=\"{{closeSheet}}\"><svg class=\"cp-ic\" viewBox=\"0 0 24 24\"><path d=\"M6 6l12 12M18 6L6 18\"/></svg></button></div>\n<p class=\"cp-big\">{{disc.phrase}}</p>\n<p class=\"cp-note\" style=\"margin-top:0\">{{disc.base}}</p>\n<sc-if value=\"{{disc.hasDots}}\" hint-placeholder-val=\"{{ true }}\">\n<div class=\"cp-dd\" aria-hidden=\"true\"><sc-for list=\"{{disc.dots}}\" as=\"d\" hint-placeholder-count=\"9\"><i class=\"{{d}}\"></i></sc-for></div>\n<p class=\"cp-note\" style=\"margin-top:2px\">{{disc.lab}}</p>\n</sc-if>\n<sc-if value=\"{{disc.hasNote}}\" hint-placeholder-val=\"{{ false }}\"><p class=\"cp-note\">{{disc.note}}</p></sc-if>\n<sc-if value=\"{{disc.isPast}}\" hint-placeholder-val=\"{{ false }}\"><p class=\"cp-note\">Cette habitude a changé : elle reste ici, au passé, comme un souvenir.</p></sc-if>\n<sc-if value=\"{{disc.hasMore}}\" hint-placeholder-val=\"{{ true }}\"><button class=\"cp-btn ghost\" type=\"button\" onClick=\"{{disc.goMore}}\">Voir dans « Aller plus loin »</button></sc-if>\n<sc-if value=\"{{disc.canHide}}\" hint-placeholder-val=\"{{ true }}\"><button class=\"cp-btn ghost\" type=\"button\" onClick=\"{{toggleHide}}\">{{disc.hideLab}}</button></sc-if>\n</section></div>\n</sc-if>\n\n<!-- ===== Feuille : son portrait et son écharpe ===== -->\n<sc-if value=\"{{showAlbum}}\" hint-placeholder-val=\"{{ false }}\">\n<div class=\"cp-scrim\"><button class=\"cp-scrim-bg\" type=\"button\" aria-label=\"Fermer\" onClick=\"{{closeSheet}}\"></button>\n<section class=\"cp-sheet\" role=\"dialog\" aria-modal=\"true\" aria-label=\"Son portrait\" style=\"max-height:94%\">\n<div class=\"cp-grab\"></div>\n<div class=\"cp-sh-h\"><h2>Son portrait</h2><button class=\"cp-x\" type=\"button\" aria-label=\"Fermer\" onClick=\"{{closeSheet}}\"><svg class=\"cp-ic\" viewBox=\"0 0 24 24\"><path d=\"M6 6l12 12M18 6L6 18\"/></svg></button></div>\n<div class=\"cp-stage\"><dc-import name=\"Filou\" situation=\"none\" age=\"{{ageSel}}\" medal=\"{{ageMedal}}\" defs=\"{{no}}\" hint-size=\"358px,270px\"></dc-import></div>\n<p class=\"cp-fam\" style=\"margin-top:2px\">Au fil des mois</p>\n<div class=\"cp-ages\" role=\"group\" aria-label=\"Âge de Filou\">\n<sc-for list=\"{{ageChips}}\" as=\"a\" hint-placeholder-count=\"3\"><button type=\"button\" class=\"{{a.cls}}\" onClick=\"{{a.pick}}\">{{a.l}}</button></sc-for>\n</div>\n<p class=\"cp-note\">Filou grandit avec l'âge de {{babyName}}. Cela ne dit rien de son rythme.</p>\n\n<p class=\"cp-fam\">Découvert par Canaille</p>\n<sc-if value=\"{{appEmpty}}\" hint-placeholder-val=\"{{ false }}\"><div class=\"cp-empty\">Pas encore de badge. Ses habitudes et ses badges apparaîtront ici, dès qu'une habitude se dessinera.</div></sc-if>\n<sc-for list=\"{{appRows}}\" as=\"e\" hint-placeholder-count=\"6\">\n<button class=\"cp-erow {{e.off}}\" type=\"button\" onClick=\"{{e.open}}\">\n<span class=\"cp-patch {{e.tint}}\"><svg class=\"cp-sym {{e.dash}}\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><use href=\"{{e.href}}\"/></svg></span>\n<span><span class=\"cp-er-t\">{{e.phrase}}</span><span class=\"cp-er-d\">{{e.sub}}</span></span>\n<svg class=\"cp-ic\" viewBox=\"0 0 24 24\" style=\"color:var(--mut)\"><path d=\"M9 6l6 6-6 6\"/></svg>\n</button>\n</sc-for>\n\n<p class=\"cp-fam\">Cousu à la main</p>\n<sc-for list=\"{{handRows}}\" as=\"e\" hint-placeholder-count=\"2\">\n<button class=\"cp-erow {{e.off}}\" type=\"button\" onClick=\"{{e.open}}\">\n<span class=\"cp-patch {{e.tint}}\"><svg class=\"cp-sym\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><use href=\"{{e.href}}\"/></svg></span>\n<span><span class=\"cp-er-t\">{{e.phrase}}</span><span class=\"cp-er-d\">{{e.sub}}</span></span>\n<svg class=\"cp-ic\" viewBox=\"0 0 24 24\" style=\"color:var(--mut)\"><path d=\"M9 6l6 6-6 6\"/></svg>\n</button>\n</sc-for>\n<button class=\"cp-btn rose\" type=\"button\" onClick=\"{{openSew}}\"><svg class=\"cp-ic\" viewBox=\"0 0 24 24\"><path d=\"M12 5v14M5 12h14\"/></svg>Coudre un souvenir</button>\n\n<p class=\"cp-fam\">Avant</p>\n<sc-for list=\"{{pastRows}}\" as=\"e\" hint-placeholder-count=\"1\">\n<button class=\"cp-erow\" type=\"button\" onClick=\"{{e.open}}\">\n<span class=\"cp-patch ti-but\" style=\"opacity:.6\"><svg class=\"cp-sym dash\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><use href=\"{{e.href}}\"/></svg></span>\n<span><span class=\"cp-er-t\">{{e.phrase}}</span><span class=\"cp-er-d\">{{e.sub}}</span></span>\n<svg class=\"cp-ic\" viewBox=\"0 0 24 24\" style=\"color:var(--mut)\"><path d=\"M9 6l6 6-6 6\"/></svg>\n</button>\n</sc-for>\n</section></div>\n</sc-if>\n\n<!-- ===== Feuille : coudre un souvenir ===== -->\n<sc-if value=\"{{showSew}}\" hint-placeholder-val=\"{{ false }}\">\n<div class=\"cp-scrim\"><button class=\"cp-scrim-bg\" type=\"button\" aria-label=\"Fermer\" onClick=\"{{closeSew}}\"></button>\n<section class=\"cp-sheet\" role=\"dialog\" aria-modal=\"true\" aria-label=\"Coudre un souvenir\">\n<div class=\"cp-grab\"></div>\n<div class=\"cp-sh-h\"><h2>Coudre un souvenir</h2><button class=\"cp-x\" type=\"button\" aria-label=\"Fermer\" onClick=\"{{closeSew}}\"><svg class=\"cp-ic\" viewBox=\"0 0 24 24\"><path d=\"M6 6l12 12M18 6L6 18\"/></svg></button></div>\n<p class=\"cp-note\" style=\"margin-top:0\">Un moment que tu as vu, cousu en rose sur son écharpe. Il ne dépend d'aucune donnée.</p>\n<span class=\"cp-lab\" style=\"margin-top:14px\">Un symbole</span>\n<div class=\"cp-pick\">\n<sc-for list=\"{{sewSyms}}\" as=\"s\" hint-placeholder-count=\"6\"><button type=\"button\" class=\"{{s.cls}}\" aria-label=\"{{s.l}}\" onClick=\"{{s.pick}}\"><svg class=\"cp-sym\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><use href=\"{{s.href}}\"/></svg>{{s.l}}</button></sc-for>\n</div>\n<label class=\"cp-lab\" for=\"sew-t\">Qu'est-ce qu'on a vu ?</label>\n<input id=\"sew-t\" class=\"cp-in\" type=\"text\" value=\"{{sewTitle}}\" placeholder=\"Par exemple : premier rire\" onInput=\"{{setSewTitle}}\">\n<label class=\"cp-lab\" for=\"sew-d\" style=\"margin-top:12px\">Quand ?</label>\n<input id=\"sew-d\" class=\"cp-in\" type=\"text\" value=\"{{sewDate}}\" onInput=\"{{setSewDate}}\">\n<button class=\"cp-btn rose\" type=\"button\" onClick=\"{{saveSew}}\">Coudre</button>\n<button class=\"cp-btn ghost\" type=\"button\" onClick=\"{{closeSew}}\">Annuler</button>\n</section></div>\n</sc-if>\n\n<!-- ===== Feuille : aller plus loin ===== -->\n<sc-if value=\"{{showMore}}\" hint-placeholder-val=\"{{ false }}\">\n<div class=\"cp-scrim\"><button class=\"cp-scrim-bg\" type=\"button\" aria-label=\"Fermer\" onClick=\"{{closeSheet}}\"></button>\n<section class=\"cp-sheet\" role=\"dialog\" aria-modal=\"true\" aria-label=\"{{more.t}}\" style=\"max-height:94%\">\n<div class=\"cp-grab\"></div>\n<div class=\"cp-sh-h\"><span class=\"cp-patch {{more.tint}}\"><svg class=\"cp-sym\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><use href=\"{{more.href}}\"/></svg></span><h2>{{more.t}}</h2><button class=\"cp-x\" type=\"button\" aria-label=\"Fermer\" onClick=\"{{closeSheet}}\"><svg class=\"cp-ic\" viewBox=\"0 0 24 24\"><path d=\"M6 6l12 12M18 6L6 18\"/></svg></button></div>\n<p class=\"cp-fam\" style=\"margin-top:4px\">En bref</p>\n<ul class=\"cp-bul\"><sc-for list=\"{{more.bul}}\" as=\"b\" hint-placeholder-count=\"3\"><li>{{b}}</li></sc-for></ul>\n<div class=\"cp-secs\">\n<sc-for list=\"{{more.sec}}\" as=\"s\" hint-placeholder-count=\"2\">\n<div class=\"cp-card\">\n<p class=\"cp-q\">{{s.q}}</p>\n<sc-if value=\"{{s.hasBars}}\" hint-placeholder-val=\"{{ false }}\"><div class=\"cp-bars\"><sc-for list=\"{{s.bars}}\" as=\"b\" hint-placeholder-count=\"6\"><div class=\"cp-bcol\"><span class=\"cp-bv\">{{b.v}}</span><div class=\"cp-bt\"><div class=\"cp-bf {{b.cls}}\" style=\"height:{{b.h}}\"></div></div><span class=\"cp-bl\">{{b.l}}</span></div></sc-for></div></sc-if>\n<sc-if value=\"{{s.hasRows}}\" hint-placeholder-val=\"{{ false }}\"><div class=\"cp-rows\"><sc-for list=\"{{s.rows}}\" as=\"r\" hint-placeholder-count=\"4\"><div class=\"cp-row\"><span class=\"cp-row-k\">{{r.k}}</span><span class=\"cp-row-v\">{{r.v}}</span><sc-if value=\"{{r.hasP}}\" hint-placeholder-val=\"{{ false }}\"><span class=\"cp-pill st-bu\">{{r.p}}</span></sc-if></div></sc-for></div></sc-if>\n<p class=\"cp-phr\" style=\"font-size:15.5px\">{{s.ph}}</p>\n<div class=\"cp-meta\"><span class=\"cp-pill {{s.stCls}}\">{{s.stLab}}</span><small>{{s.base}}</small></div>\n</div>\n</sc-for>\n</div>\n</section></div>\n</sc-if>\n</dc-import>\n</div>";
